import hashlib,json,math,os,plistlib,re,statistics,subprocess,tempfile,time
from pathlib import Path
root=Path('/private/tmp/logex-audit-130-02gwayfm')
source=root/'current-c63fb9ed';image=root/'exfat-raw.dmg';mount=root/'exfat'
assert root.is_dir() and not root.is_symlink() and image.is_file() and not image.is_symlink()
os.chdir(source)
os.environ['PATH']=str(Path.home()/'.cargo/bin')+os.pathsep+os.environ.get('PATH','')
binaries={'base':root/'baseline-v3-09a63f55-publication-tests','candidate':root/'ordered-c63fb9ed-publication-tests'}
assert all(p.is_file() and not p.is_symlink() for p in binaries.values())
profiles=[('few-logs',128,1,2048,'historical',False),('short',128,128,2048,'historical',False),('per-block-live',128,128,2048,'live',True)]

def attached():
 info=plistlib.loads(subprocess.check_output(['hdiutil','info','-plist']))
 matches=[x for x in info.get('images',[]) if Path(x['image-path']).resolve()==image.resolve()]
 assert len(matches)<=1
 return matches[0] if matches else None

def run(filesystem,parent):
 with tempfile.TemporaryDirectory(prefix='ordered-c63fb9ed-perf-',dir=parent) as temp:
  temp=Path(temp);device=os.stat(temp).st_dev
  result_path=root/('ordered-c63fb9ed-'+filesystem+'-performance.jsonl')
  assert not result_path.exists()
  with result_path.open('w') as output:
   meta={'kind':'environment','original':'09a63f555db19a03850ce5eba6f149957febaf3b','candidate':'c63fb9edd0783e75e43d1f271a3776d52361ff50','filesystem':filesystem,'device':device,'binary_sha256':{k:hashlib.sha256(p.read_bytes()).hexdigest() for k,p in binaries.items()},'rustc':subprocess.check_output(['rustc','-Vv'],text=True),'hardware':subprocess.check_output(['sysctl','-n','hw.model','hw.memsize','hw.ncpu'],text=True),'os':subprocess.check_output(['sw_vers'],text=True),'space':subprocess.check_output(['df','-h',str(temp)],text=True),'load':subprocess.check_output(['sysctl','vm.loadavg'],text=True),'fixture_sha256':hashlib.sha256((source/'crates/logex-storage/tests/ingestion_publication.rs').read_bytes()).hexdigest(),'baseline_fixture_sha256':hashlib.sha256((root/'baseline-v3-09a63f55/crates/logex-storage/tests/ingestion_publication.rs').read_bytes()).hexdigest(),'runner_source':Path(__file__).read_text(),'conditions':'5 alternating process pairs x 3 samples; fresh directories; OS cache not evicted; no concurrent audit builds/tests on this host; other host load not controlled; original history omitted fsync, candidate includes final ordered checkpoint publication; its shared recovery window across pending/published work is 32 MiB/64 calls/5 seconds, checked at batch/idle boundaries, plus oversized-batch exception. Explicit checkpoint_durable is not requested. This changes acknowledged power-loss durability; exact clean reopen does not establish power-failure behavior; exact row/progress/reopen oracles; storage calls, not peer throughput. ExFAT is a disposable image on internal APFS, not the protected USB volume.'}
   output.write(json.dumps(meta)+'\n');output.flush()
   for profile,blocks,rows,batch,route,each in profiles:
    for pair in range(5):
     for label in (['base','candidate'] if pair%2==0 else ['candidate','base']):
      assert os.stat(temp).st_dev==device
      if filesystem=='exfat':assert attached() is not None
      env={**os.environ,'TMPDIR':str(temp),'LOGEX_PUBLICATION_HEADER_FIELDS':'minimal','LOGEX_PUBLICATION_BLOCKS':str(blocks),'LOGEX_PUBLICATION_ROWS_PER_BLOCK':str(rows),'LOGEX_PUBLICATION_HISTORY_BLOCKS':str(batch),'LOGEX_PUBLICATION_SEGMENT_ROWS':'1000000','LOGEX_PUBLICATION_WARM_HEADERS':'8192','LOGEX_PUBLICATION_REPEATS':'3','LOGEX_PUBLICATION_ROUTE':route,'LOGEX_PUBLICATION_CHECKPOINT_EACH_BLOCK':str(int(each))}
      log_path=root/f'ordered-c63fb9ed-{filesystem}-{profile}-{pair}-{label}.log'
      with log_path.open('w') as log:r=subprocess.run(['/usr/bin/time','-l',str(binaries[label]),'benchmark_sync_storage_publication','--ignored','--nocapture','--test-threads=1'],env=env,stdout=log,stderr=subprocess.STDOUT)
      if r.returncode:raise RuntimeError(str(log_path)+': '+str(r.returncode))
      for line in log_path.read_text().splitlines():
       if '{' in line:
        try:record=json.loads(line[line.index('{'):])
        except json.JSONDecodeError:continue
        output.write(json.dumps({**record,'profile':profile,'revision':label,'pair':pair})+'\n')
       elif 'maximum resident set size' in line:output.write(json.dumps({'kind':'rss','profile':profile,'revision':label,'pair':pair,'bytes':int(line.split()[0])})+'\n')
      output.flush();print(filesystem,profile,pair,label,'passed',flush=True)
   records=[json.loads(x) for x in result_path.read_text().splitlines()]
   for profile,*_ in profiles:
    metrics=sorted({r['metric'] for r in records if r.get('profile')==profile and r.get('kind')=='sample'})
    for metric in metrics:
     vals={v:[x['elapsed_ms'] for x in records if x.get('kind')=='sample' and x.get('profile')==profile and x.get('metric')==metric and x['revision']==v] for v in binaries}
     med={v:statistics.median(xs) for v,xs in vals.items()}
     summary={'kind':'summary','profile':profile,'metric':metric,'median_ms':med,'p95_ms':{v:sorted(xs)[math.ceil(.95*len(xs))-1] for v,xs in vals.items()},'change_percent':(med['candidate']/med['base']-1)*100,'samples':{v:len(xs)for v,xs in vals.items()}}
     output.write(json.dumps(summary)+'\n');print(filesystem,summary,flush=True)
assert attached() is None
run('apfs',root)
assert mount.is_dir() and not mount.is_symlink() and os.stat(mount).st_dev==os.stat(root).st_dev
subprocess.check_call(['hdiutil','attach',str(image),'-mountpoint',str(mount),'-nobrowse'])
try:
 selected=attached();assert selected is not None
 assert any(x.get('mount-point')==str(mount) for x in selected['system-entities'])
 volume=plistlib.loads(subprocess.check_output(['diskutil','info','-plist',str(mount)]))
 assert volume['FilesystemType']=='exfat'
 run('exfat',mount)
finally:
 selected=attached()
 if selected is not None:
  assert any(x.get('mount-point')==str(mount) for x in selected['system-entities'])
  devices=[x['dev-entry'] for x in selected['system-entities'] if re.fullmatch(r'/dev/disk[0-9]+',x.get('dev-entry',''))]
  assert len(devices)==1
  subprocess.check_call(['hdiutil','detach',devices[0]])
 assert attached() is None
 print('Disposable image detached',flush=True)
